use actix_web::{post, web, App, HttpResponse, HttpServer, Responder};
use serde::{Deserialize, Serialize};
use std::fs::{self, File};
use std::io::{self, Read};
use std::path::PathBuf;

#[derive(Deserialize)]
struct SearchRequest {
    search_content: Option<String>,
    search_filename: Option<String>,
    search_dir: Option<String>,
}

#[derive(Serialize)]
struct SearchResponse {
    files: Vec<String>,
}

#[post("/search")]
async fn search_files(req: web::Json<SearchRequest>) -> impl Responder {
    let base_path = PathBuf::from("/data");
    let mut found_files = Vec::new();

    if let Some(search_dir) = &req.search_dir {
        let search_path = base_path.join(search_dir);
        if let Err(_) = fs::read_dir(&search_path) {
            return HttpResponse::BadRequest().finish();
        }

        for entry in fs::read_dir(search_path).unwrap() {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_file() {
                    let filename = path.file_name().unwrap().to_string_lossy().to_string();
                    let mut content = String::new();
                    if let Ok(mut file) = File::open(&path) {
                        if let Err(_) = file.read_to_string(&mut content) {
                            continue;
                        }
                    }

                    let matches_filename = req.search_filename.as_ref().map_or(true, |name| filename.contains(name));
                    let matches_content = req.search_content.as_ref().map_or(true, |content| content.is_empty() || content.chars().all(|c| content.contains(c)));

                    if matches_filename || matches_content {
                        found_files.push(path.to_string_lossy().to_string());
                    }
                }
            }
        }
    }

    HttpResponse::Ok().json(SearchResponse { files: found_files })
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .service(search_files)
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}
